import type {FC, ReactNode} from 'react';
import React from 'react';

import {cnEntitiesSuggestItem} from './EntitiesSuggestItem.classname';

import './EntitiesSuggestItem.scss';

export type EntitiesSuggestItemProps = {
    icon?: ReactNode;
    id: number | string;
    name: string;
    description?: string;
    className?: string;
};

export const EntitiesSuggestItem: FC<EntitiesSuggestItemProps> = ({
    icon,
    name,
    description,
    className,
}) => {
    return (
        <div className={cnEntitiesSuggestItem(null, className)}>
            {icon}
            <div>
                <div className={cnEntitiesSuggestItem('name')}>{name}</div>
                <div className={cnEntitiesSuggestItem('description')}>{description}</div>
            </div>
        </div>
    );
};
